local config = {
  ui_story_31880401_1_dialog_content = "<color=#e8d9bb>Sebuah puisi berbunyi...</color>",
  ui_story_31880401_2_dialog_content = "<color=#e8d9bb>\"Raja Ji, kerajaan bawahan dari Kekaisaran Zhao, memerintahkan Putri Zhuohua untuk melakukan perjalanan sebagai utusan ke negeri barat.\"</color>",
  ui_story_31880401_3_dialog_content = "<color=#e8d9bb>\"Tanpa rasa takut, dia menjelajahi gunung dan samudra, bahkan di tengah pertempuran perbatasan, menunjukkan keberanian yang tak goyah dalam menghadapi kesulitan.\"</color>",
  ui_story_31880401_4_dialog_content = "<color=#e8d9bb>\"Saat berkelana di gurun pasir yang luas, kesepian dan keputusasaan memenuhi hatinya. Di bawah langit yang dingin dan jernih, perasaannya menjadi rumit dan intens.\"</color>",
  ui_story_31880401_5_dialog_content = "<color=#e8d9bb>\"Menambah kesedihannya, sekawanan angsa menjerit ke arah Twin Pavilions Bay, dan dia merasa sangat terisolasi dan rindu akan kampung halamannya.\"</color>",
  ui_story_31880401_6_dialog_content = "<color=#e8d9bb>Terlepas dari banyaknya cobaan dan kesulitan yang dihadapi, Putri Zhuohua akhirnya tiba di tanah barat, dan ia pun beristirahat sejenak di Twin Pavilions Bay.</color>",
  ui_story_31880401_7_dialog_content = "<color=#e8d9bb>Seperti namanya, Twin Pavilions Bay adalah kota yang terbagi menjadi dua, dengan satu setengah dikuasai oleh Umbraton dan setengah lainnya oleh Lin Guild.</color>",
  ui_story_31880401_8_dialog_content = "<color=#e8d9bb>Di setengah kota milik Serikat Lin, jalan-jalan dan bangunan tampak tidak berbeda dengan kota besar Zhao Kekaisaran. Terkadang hal ini membuat orang bingung, tidak tahu di mana mereka berada.</color>",
  ui_story_31880401_9_dialog_content = "<color=#e8d9bb>Kuda Naga Bai, Jiu Wukong, Meow Bajie, dan Zen Wujing menatap kagum pada setengah kota Umbraton, hati mereka penuh ambisi.</color>",
  ui_story_31880401_10_dialog_content = "<color=#e8d9bb>Namun, Putri Zhuohua menatap kosong ke cermin, pikirannya tampaknya dipenuhi oleh sesuatu yang mengganggu...</color>",
  ui_story_31880401_11_dialog_content = "<color=#e8d9bb>Wajah cantik yang terpantul di cermin mengingatkan pada sebuah puisi lainnya...</color>",
  ui_story_31880401_12_dialog_content = "<color=#e8d9bb>\"Kulit seputih es, dan wajah sehalus ukiran giok. Pipi merona dan bibir merahnya menghiasi dunia ini dengan warna dan keindahan.\"</color>",
  ui_story_31880401_13_dialog_content = "<color=#e8d9bb>\"Dengan lembut dia melangkah, seanggun dan ringan seperti angin yang berhembus di antara ranting pohon willow. Matanya mengingatkan pada kelembutan kelopak bunga yang jatuh perlahan di atas kolam air.\"</color>",
  ui_story_31880401_14_dialog_content = "Wukong, sudah berapa lama sejak kita mengirim surat kepada Raja Singa Obsidian untuk meminta audiensi?",
  ui_story_31880401_15_dialog_content = "Lima belas hari, jika kita termasuk hari ini.",
  ui_story_31880401_16_dialog_content = "Raja Singa Obsidian sepertinya terlalu sibuk untuk membalas kita.",
  ui_story_31880401_17_dialog_content = "Tak bagus! Tak bagus!",
  ui_story_31880401_18_dialog_content = "Kenapa kamu sangat panik, Bajie?",
  ui_story_31880401_19_dialog_content = "Aku pergi memeriksa rumah Raja Singa Obsidian, dan aku menemukan surat kita di tempat sampah! Mereka membuangnya!",
  ui_story_31880401_20_dialog_content = "Apa?",
  ui_story_31880401_21_dialog_content = "Wujing juga melihatnya! Tanya dia jika kamu tidak percaya padaku!",
  ui_story_31880401_22_dialog_content = "Dia mengatakan yang sebenarnya, Yang Mulia. Saya juga melihatnya.",
  ui_story_31880401_23_dialog_content = "...Tidak heran kami belum menerima balasan.",
  ui_story_31880401_24_dialog_content = "Sepertinya kita hampir tidak pantas mendapat perhatian dari Raja Singa Obsidian.",
  ui_story_31880401_25_dialog_content = "Umbraton bukan satu-satunya tempat di Astra. Jika kita terus bepergian ke barat, kita bisa mengunjungi Illumina atau bahkan Eraveil.",
  ui_story_31880401_26_dialog_content = "Sepakat! Jika mereka tidak mau memberi kita waktu, maka kita pun seharusnya tidak!",
  ui_story_31880401_27_dialog_content = "Raja Singa ini sepertinya tidak layak menjadi raja. Menurutku, dia hanya singa bodoh biasa saja!",
  ui_story_31880401_28_dialog_content = "Bagaimana menurut Anda, Yang Mulia? Haruskah saya pergi dan memberi mereka pelajaran?",
  ui_story_31880401_29_dialog_content = "Sama sekali tidak mau.",
  ui_story_31880401_30_dialog_content = "Kami tidak di sini untuk membuat masalah. Ingatlah untuk tetap fokus pada tujuan utama kita.",
  ui_story_31880401_31_dialog_content = "Selalu saja \"tujuan akhir\" ini dan \"tujuan akhir\" itu. Bagaimana aku bisa mengingatnya jika aku bahkan tidak diizinkan untuk keluar selain memeriksa singa itu?",
  ui_story_31880401_32_dialog_content = "Cukup, Bajie.",
  ui_story_31880401_33_dialog_content = "Selama beberapa hari terakhir, saya khawatir kita akan kehilangan kesempatan untuk bertemu Raja Singa Obsidian jika kita berkeliaran terlalu banyak.",
  ui_story_31880401_34_dialog_content = "Tapi sepertinya kita tidak perlu khawatir tentang itu lagi.",
  ui_story_31880401_35_dialog_content = "Di sini, Wukong. Ambil perak ini, bersama Bajie dan Wujing, dan pergilah bersenang-senang.",
  ui_story_31880401_36_dialog_content = "Tapi bagaimana dengan Anda, Yang Mulia?",
  ui_story_31880401_37_dialog_content = "Kurasa aku akan tinggal di sini dan beristirahat sebentar. Kalian bertiga silakan lanjut.",
  ui_story_31880401_38_dialog_content = "Istirahat yang cukup, ya, Yang Mulia! Nanti kami akan membawakan Anda buah manisan!",
  ui_story_31880401_39_dialog_content = "Yang Mulia! Sudah bangunkah Anda?",
  ui_story_31880401_40_dialog_content = "Buah karamel ini rasanya persis seperti yang ada di rumah! Ayo, coba beberapa!",
  ui_story_31880401_41_dialog_content = "Hah? Di-Di mana Yang Mulia?!",
  ui_story_31880401_42_dialog_content = "Dia tidak meninggalkan kita untuk pergi bersenang-senang sendirian, 'kan?!",
  ui_story_31880401_43_dialog_content = "Tidak, selendangnya masih di sini, yang berarti Yang Mulia kemungkinan tidak pergi dengan kemauan sendiri. Jika ada apa-apa...",
  ui_story_31880401_44_dialog_content = "Jika ada...?",
  ui_story_31880401_45_dialog_content = "Sepertinya ini penculikan.",
  ui_story_31880401_46_dialog_content = "Apa?!",
  ui_story_31880401_47_dialog_content = "Tapi kita tidak mengganggu siapa pun di sini! Mengapa mereka menculik Yang Mulia?",
  ui_story_31880401_48_dialog_content = "Selain kita, hanya ada satu orang yang tahu bahwa Yang Mulia ada di sini sekarang.",
  ui_story_31880401_49_dialog_content = "Raja Singa Obsidian?",
  ui_story_31880401_50_dialog_content = "Aku akan berubah menjadi serangga dan pergi menyelidiki. Kalian berdua tetap di sini dan jaga kepala kalian tetap rendah.",
  ui_story_31880401_51_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_31880401_52_dialog_content = "Siapa yang tahu kalau pria ini punya ruang tersembunyi di rumahnya seperti ini?",
  ui_story_31880401_53_dialog_content = "Hmm? Ada seseorang di depan!",
  ui_story_31880401_54_dialog_content = "Lepaskan aku!",
  ui_story_31880401_55_dialog_content = "Hahaha! Bukankah perjuanganmu sekarang ini hampir sia-sia?",
  ui_story_31880401_56_dialog_content = "Kamu... Apa sebenarnya yang sedang kamu rencanakan?",
  ui_story_31880401_57_dialog_content = "Saya bisa menanyakan hal yang sama kepada Anda. Katakan padaku, mengapa Anda datang ke Astra?",
  ui_story_31880401_58_dialog_content = "Saya menjelaskannya dengan sangat jelas dalam surat itu. Kami di sini untuk misi pertukaran budaya...",
  ui_story_31880401_59_dialog_content = "Sebuah \"pertukaran budaya\"? Cara menyatakannya sangat menyenangkan.",
  ui_story_31880401_60_dialog_content = "Anda bisa berhenti berpura-pura sekarang. Kami tahu Anda bekerja sebagai mata-mata untuk pihak timur.",
  ui_story_31880401_61_dialog_content = "Meskipun Anda mengklaim mencari pertukaran budaya, yang sebenarnya Anda cari adalah rahasia tersembunyi Astra.",
  ui_story_31880401_62_dialog_content = "Kamu salah!",
  ui_story_31880401_63_dialog_content = "Lalu ceritakan padaku, apa yang akan terjadi jika kita berhasil membuat perjanjian dagang?",
  ui_story_31880401_64_dialog_content = "Baik timur maupun barat akan mendapatkan manfaat besar dari hal ini. Mesin-mesin dari barat akan muncul di timur, dan kecerdikan timur akan datang ke sini.",
  ui_story_31880401_65_dialog_content = "Betapa salahnya kamu.",
  ui_story_31880401_66_dialog_content = "Ketika saatnya tiba, orang-orang Anda akan menurunkan harga barang-barang Anda dan membanjiri seluruh Astra dengan mereka.",
  ui_story_31880401_67_dialog_content = "Setelah pasar domestik kita lumpuh dan rakyat kita tidak memiliki cara untuk mencari nafkah...",
  ui_story_31880401_68_dialog_content = "Kaisar Anda akan mengirim pasukannya untuk menyerang dan menaklukkan seluruh Astra!",
  ui_story_31880401_69_dialog_content = "Itu absurd!",
  ui_story_31880401_70_dialog_content = "Aku tidak bepergian ribuan mil ke Astra hanya untuk menciptakan lebih banyak konflik antara budaya kita...",
  ui_story_31880401_71_dialog_content = "Oh? Masih menyangkalnya?",
  ui_story_31880401_72_dialog_content = "Kalau begitu, izinkan saya mengajukan satu pertanyaan terakhir.",
  ui_story_31880401_73_dialog_content = "Sumber informasi saya mengatakan bahwa siapa pun yang mengambil kekuatan dalam tubuhmu bisa menjadi Aurorian paling kuat yang ada. Apakah itu benar?",
  ui_story_31880401_74_dialog_content = "A... Apa yang kamu rencanakan untuk lakukan padaku?!",
  ui_story_31880401_75_dialog_content = "Oh, lihat kamu, rupanya memang benar.",
  ui_story_31880401_76_dialog_content = "...!!!",
  ui_story_31880401_77_dialog_content = "Nguung, nguung, nguung!",
  ui_story_31880401_78_dialog_content = "Dari mana bug ini berasal?",
  ui_story_31880401_79_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_31880401_80_dialog_content = "Apa kaubilang?!",
  ui_story_31880401_81_dialog_content = "Jadi monster itu ingin mencuri kekuatan Yang Mulia?",
  ui_story_31880401_82_dialog_content = "Mengapa saya tidak memikirkan kemungkinan itu...?",
  ui_story_31880401_83_dialog_content = "Hei, tunggu sebentar. Tanpa kehadiran Yang Mulia, bukankah itu berarti aku bisa pergi ke mana saja yang aku inginkan?",
  ui_story_31880401_84_dialog_content = "...",
  ui_story_31880401_85_dialog_content = "Hei, hei! Yang Mulia bilang kamu nggak boleh memukul saya!",
  ui_story_31880401_86_dialog_content = "Aku tidak akan melakukannya. Sekarang dengarkan dengan saksama, kita masing-masing memiliki tugas yang harus dilakukan sekarang...",
  ui_story_31880401_87_dialog_content = "Keluarlah, monster singa! Aku tahu kamu ada di sana!",
  ui_story_31880401_88_dialog_content = "Jika kamu punya keberanian untuk menculik putri kami, kamu harus punya keberanian untuk mengakuinya juga!",
  ui_story_31880401_89_dialog_content = "Bagaimana berani kamu menggonggong di pintu rumahku seperti anjing liar?",
  ui_story_31880401_90_dialog_content = "D-Dia keluar... Sekarang terserah padamu, Wujing!",
  ui_story_31880401_91_dialog_content = "Ya, ya, aku tahu.",
  ui_story_31880401_92_dialog_content = "Bersiaplah, Raja Singa Obsidian! Kini setelah kau menculik putri kami, aku tak punya alasan untuk menahan diri!",
  ui_story_31880401_93_dialog_content = "Rasakan ini!",
  ui_story_31880401_94_dialog_content = "Hmph, trik sepele semacam itu.",
  ui_story_31880401_95_dialog_content = "Argh…",
  ui_story_31880401_96_dialog_content = "D-Dia terlalu kuat! Kita harus lari saja—",
  ui_story_31880401_97_dialog_content = "Mau pergi secepat ini? Apakah kamu lupa di mana kamu sekarang?",
  ui_story_31880401_98_dialog_content = "Kamu tidak akan bisa kabur begitu mudah!",
  ui_story_31880401_99_dialog_content = "...",
  ui_story_31880401_100_dialog_content = "Tunggu, apa mereka... mencoba memancingku pergi?",
  ui_story_31880401_101_dialog_content = "Urgh... Apa...",
  ui_story_31880401_102_dialog_content = "Hmph, jangan repot-repot mencari. Putri sudah aman dan selamat sekarang.",
  ui_story_31880401_103_dialog_content = "Sekarang kita benar-benar bisa bersenang-senang.",
  ui_story_31880401_104_dialog_content = "Rasakan ini!",
  ui_story_31880401_105_dialog_content = "Tunggu!",
  ui_story_31880401_106_dialog_content = "Kuda Naga Bai? Bukankah kamu seharusnya mengawasi peralatan kita?",
  ui_story_31880401_107_dialog_content = "Aku menemukan putri Raja Singa Obsidian—Fairy Bell.",
  ui_story_31880401_108_dialog_content = "Semuanya, tolong turunkan senjata kalian.",
  ui_story_31880401_109_dialog_content = "Master...",
  ui_story_31880401_110_dialog_content = "\"Master\"? Itu baru. Kenapa ayahmu memanggilmu begitu?",
  ui_story_31880401_111_dialog_content = "Lihat saja sendiri.",
  ui_story_31880401_112_dialog_content = "<color=#e8d9bb>Puf!</color>",
  ui_story_31880401_113_dialog_content = "...",
  ui_story_31880401_114_dialog_content = "Apa ini...?",
  ui_story_31880401_115_dialog_content = "Ini Frankel, hantu kesayanganku.",
  ui_story_31880401_116_dialog_content = "Tampaknya Frankel mengambil penampilan ayahku saat kami pergi, dan menimbulkan banyak masalah untukmu.",
  ui_story_31880401_117_dialog_content = "Oh? Jadi yang menyebut saya anjing liar ternyata adalah hewan peliharaan keluarga, ya?",
  ui_story_31880401_118_dialog_content = "Huu-huu...",
  ui_story_31880401_119_dialog_content = "Jaga bicaramu, Bajie.",
  ui_story_31880401_120_dialog_content = "Hmph! Bagaimana Anda masih bisa begitu sopan kepada mereka, Yang Mulia? Apakah Anda sudah lupa apa yang terjadi pada Anda?",
  ui_story_31880401_121_dialog_content = "Ini salahku karena tidak melatih Frankel dengan cukup baik.",
  ui_story_31880401_122_dialog_content = "Mohon terima permintaan maaf tulus saya!",
  ui_story_31880401_123_dialog_content = "Aku akan pastikan untuk lebih mengawasi Frankel, agar hal ini tidak terjadi lagi.",
  ui_story_31880401_124_dialog_content = "Sebagai permintaan maaf, izinkan saya untuk menanggung biaya perjalanan Anda saat melanjutkan perjalanan ke barat.",
  ui_story_31880401_125_dialog_content = "Dan jika Anda mau... saya juga bisa menemani Anda untuk menemui ayah saya, Tuan Putri.",
  ui_story_31880401_126_dialog_content = "Sangat dihargai.",
  ui_story_31880401_127_dialog_content = "<color=#e8d9bb>Tak lama kemudian, Tuan Putri Zhuohua akhirnya berhasil bertemu dengan Raja Singa Obsidian, penguasa Umbraton.</color>",
  ui_story_31880401_128_dialog_content = "<color=#e8d9bb>Tapi, apakah dia benar-benar mampu menyelesaikan misi pertukaran budayanya?",
  ui_story_31880401_129_dialog_content = "<color=#e8d9bb>Baca bab berikutnya untuk mengetahuinya!</color>",
  ui_story_31880401_130_dialog_content = "Wow, buku ini tampaknya...",
  ui_story_31880401_131_option_content = "Sulit dipahami.",
  ui_story_31880401_132_dialog_content = "Apakah novel-novel di timur benar-benar harus begitu sulit untuk dibaca?",
  ui_story_31880401_133_dialog_content = "Heheh, kami menyebutnya \"puisi tujuh karakter.\"",
  ui_story_31880401_134_dialog_content = "Para sastrawan di Zhao suka menulis dan membaca puisi seperti ini untuk mengungkapkan perasaan mereka.",
  ui_story_31880401_135_dialog_content = "Tidak jarang melihat mereka di novel-novel kita juga.",
  ui_story_31880401_136_option_content = "Sungguh menarik!",
  ui_story_31880401_137_dialog_content = "Saya rasa belum pernah saya membaca novel yang begitu imajinatif...",
  ui_story_31880401_138_dialog_content = "Rasanya seperti aku mengenal karakter-karakter ini dalam kehidupan nyata, tetapi mereka terlihat jauh lebih canggih dalam cerita.",
  ui_story_31880401_139_dialog_content = "Kamu benar, novel ini benar-benar menarik!",
  ui_story_31880401_140_dialog_content = "Sepertinya membagikan novel ini denganmu memang pilihan yang tepat.",
  ui_story_31880401_141_dialog_content = "Penulisnya juga bekerja sangat cepat!",
  ui_story_31880401_142_dialog_content = "Kalian belum lama berada di Astra, tapi cerita kalian sudah tersebar di seluruh negeri kami!",
  ui_story_31880401_143_dialog_content = "Hmph, sepertinya ini novel murahan lagi deh.",
  ui_story_31880401_144_dialog_content = "Saya kebetulan adalah seorang dokter terkenal dan dihormati yang membantu orang yang terluka dan menderita.",
  ui_story_31880401_145_dialog_content = "Tapi cerita ini membuatku terdengar seperti kucing yang cengeng dan malas!",
  ui_story_31880401_146_dialog_content = "Apa-apaan ini!",
  ui_story_31880401_147_dialog_content = "Oh, jangan melihatnya seperti itu.",
  ui_story_31880401_148_dialog_content = "Saat bepergian keliling dunia seperti kita ini, memiliki identitas lain sama saja dengan memiliki lapisan perlindungan tambahan.",
  ui_story_31880401_149_dialog_content = "Saya rasa novel-novel ini ditulis dengan cukup baik.",
  ui_story_31880401_150_dialog_content = "Apakah kamu memiliki identitas lain, Tianxian?",
  ui_story_31880401_151_dialog_content = "Sekarang, kenapa kamu menanyakan hal seperti itu? Rahasia itu memang tidak seharusnya dibagikan, tahu!",
  ui_story_31880401_152_dialog_content = "Tunggu, kembali...",
  ui_story_31880401_153_dialog_content = "Penyelidikan saya telah selesai, Yang Mulia.",
  ui_story_31880401_154_dialog_content = "Orang yang menerbitkan novel-novel ini adalah seorang pria dari Rediesel Desert bernama Jomu.",
  ui_story_31880401_155_dialog_content = "Penulis sepertinya juga bukan berasal dari Zhao.",
  ui_story_31880401_156_dialog_content = "Orang ini Jomu sepertinya sedang merencanakan perjalanan ke Zhao untuk mengembangkan kepentingan bisnisnya.",
  ui_story_31880401_157_dialog_content = "Apakah kamu perlu aku singkirkan dia?",
  ui_story_31880401_158_dialog_content = "Oh? Saya jujur berpikir bahwa novel-novel ini ditulis oleh salah satu warga negara kita.",
  ui_story_31880401_159_dialog_content = "Saya tidak menyangka ada seseorang di Astra yang begitu menguasai gaya sastra Zhao!",
  ui_story_31880401_160_dialog_content = "Buku gratis yang kamu bawa dari Zhou telah banyak beredar di sini. Saya percaya ini mungkin ada kaitannya dengan hal tersebut.",
  ui_story_31880401_161_dialog_content = "Sepertinya tidak ada kekurangan bakat di Astra ya.",
  ui_story_31880401_162_dialog_content = "Dan Jomu...?",
  ui_story_31880401_163_dialog_content = "Dia telah berprestasi, jadi kita harus mendukung usahanya.",
  ui_story_31880401_164_dialog_content = "Sebagai utusan ke Astra, inilah jenis pertukaran budaya yang ingin saya promosikan.",
  ui_story_31880401_165_dialog_content = "Meskipun cerita dalam novel-novel ini telah sangat dilebih-lebihkan, itu tidak mengurangi nilai mereka.",
  ui_story_31880401_166_dialog_content = "Ekspresi dari berbagai pandangan dan ideologi...",
  ui_story_31880401_167_dialog_content = "Ini adalah bagian dari kemakmuran budaya yang saya cari.",
  ui_story_31880401_168_dialog_content = "Tidak hanya itu...",
  ui_story_31880401_169_dialog_content = "\"Kulit seputih es, dan wajah sehalus ukiran giok. Pipi merona dan bibir merahnya mengisi dunia ini dengan warna dan keindahan.\"",
  ui_story_31880401_170_dialog_content = "\"Dia melangkah lembut, seanggun dan ringan seperti angin yang berhembus di antara ranting pohon willow. Matanya mengingatkan pada kelembutan kelopak bunga yang jatuh perlahan di atas kolam air.\"",
  ui_story_31880401_171_dialog_content = "Sebodoh apapun kedengarannya, aku masih cukup menyukai kalimat-kalimat ini.",
  ui_story_31880401_172_dialog_content = "Hehehe!",
  ui_story_31880601_1_dialog_content = "Suara ombak yang berbisik lembut di malam hari, dan bayangan yang berkelip dalam cahaya lilin...",
  ui_story_31880601_2_dialog_content = "Malam ini sangat indah.",
  ui_story_31880601_3_dialog_content = "Dia.",
  ui_story_31880601_4_dialog_content = "Sejak meninggalkan tanah airku untuk Kerajaan Ji... Saya jarang memiliki kesempatan untuk menikmati waktu santai seperti ini.",
  ui_story_31880601_5_dialog_content = "Terima kasih banyak sudah mengundangku untuk mengagumi bulan dari pantai.",
  ui_story_31880601_6_dialog_content = "Tawaran murah hati Anda telah memberikan saya banyak kebahagiaan hari ini.",
  ui_story_31880601_7_dialog_content = "Kamu tidak perlu terlalu sopan! Aku juga sedang menikmati waktu ini...",
  ui_story_31880601_8_dialog_content = "Heheh, sepertinya menikmati pemandangan bulan hari ini sukses besar untuk kita berdua.",
  ui_story_31880601_9_dialog_content = "Izinkan aku mengajak bersulang untukmu, temanku...",
  ui_story_31880601_10_dialog_content = "Ahh, suara ombak sungguh menenangkan... Benar-benar mengingatkan pada kenangan tertentu di masa lalu.",
  ui_story_31880601_11_dialog_content = "Ingatan tertentu?",
  ui_story_31880601_12_dialog_content = "Ya. Saat itu, saya baru saja tiba di Kerajaan Ji, dan saya menghabiskan banyak waktu di dekat pelabuhan.",
  ui_story_31880601_13_dialog_content = "Tanah air saya, Kerajaan Ye, dikenal karena keahlian kerajinannya, serta pengetahuan mendalam tentang mesin...",
  ui_story_31880601_14_dialog_content = "Tapi aku belum pernah menemui negeri yang begitu makmur dalam perdagangan dan persaingan. Sungguh pemandangan yang luar biasa.",
  ui_story_31880601_15_dialog_content = "Ini adalah pengalaman yang sangat membuka mata bagi seseorang yang baru saja tiba... Dulu, saya sering menatap ke kejauhan, tenggelam dalam pikiran sendiri.",
  ui_story_31880601_16_dialog_content = "Di cakrawala, di mana langit yang tak terbatas bertemu dengan laut yang luas, banyak kapal yang membawa berbagai keajaiban berlayar bolak-balik...",
  ui_story_31880601_17_dialog_content = "Uh-huh...",
  ui_story_31880601_18_dialog_content = "Ada masalah? Atau sudah terlalu larut untuk kamu?",
  ui_story_31880601_19_option_content = "Hah? Tidak... Tolong lanjutkan...",
  ui_story_31880601_20_option_content = "Aku hanya... sedikit lelah...",
  ui_story_31880601_21_dialog_content = "Heheh, silakan istirahatkan mata sebentar.",
  ui_story_31880601_22_dialog_content = "Di sini, di sebelahku...",
  ui_story_31880601_23_dialog_content = "...",
  ui_story_31880601_24_dialog_content = "... Hah? Di mana aku? Tempat apa ini?",
  ui_story_31880601_25_dialog_content = "Permisi, tapi apakah kamu baik-baik saja?",
  ui_story_31880601_26_dialog_content = "D... Dantang?",
  ui_story_31880601_27_dialog_content = "Hmm? Aku tidak percaya kita pernah bertemu sebelumnya. Bagaimana Anda tahu namaku, Pak?",
  ui_story_31880601_28_dialog_content = "Bisakah itu berarti... Aku sudah menjadi terkenal?",
  ui_story_31880601_29_dialog_content = "Uh, bagaimana cara menjelaskannya... Aku cukup yakin aku sedang bermimpi sekarang.",
  ui_story_31880601_30_dialog_content = "Heheh, cukup menarik jika ini semua hanyalah mimpi.",
  ui_story_31880601_31_dialog_content = "Katakan padaku, apa pendapat seorang pemimpi sepertimu tentang tempat ini?",
  ui_story_31880601_32_dialog_content = "Ini pertama kalinya kamu di pelabuhan Kerajaan Ji, benar?",
  ui_story_31880601_33_dialog_content = "Pertama kali dalam mimpi.",
  ui_story_31880601_34_dialog_content = "Lalu sepertinya kamu membutuhkan seorang pemandu.",
  ui_story_31880601_35_dialog_content = "Sebenarnya, saya juga belum lama berada di kota ini.",
  ui_story_31880601_36_dialog_content = "Tapi aku cukup akrab dengan bagian kota ini, karena sering datang ke sini.",
  ui_story_31880601_37_dialog_content = "Kamu sangat diterima untuk bergabung denganku, jika kamu mau?",
  ui_story_31880601_38_dialog_content = "Dalam beberapa menit, kita seharusnya bisa melihat banyak kapal besar.",
  ui_story_31880601_39_dialog_content = "Kapal besar?",
  ui_story_31880601_40_dialog_content = "Ya, yang sangat besar sebesar... Oh lihat, mereka ada di sini!",
  ui_story_31880601_41_dialog_content = "Sebesar rumah, dan layar besar mereka mengembang seperti awan di langit... Sungguh menakjubkan.",
  ui_story_31880601_42_dialog_content = "Saya berdoa semoga suatu hari nanti bisa naik salah satu kapal itu.",
  ui_story_31880601_43_dialog_content = "Mau pergi ke mana?",
  ui_story_31880601_44_dialog_content = "Ke mana aku harus pergi? Kalau dipikir-pikir... Aku belum pernah terlalu memikirkannya.",
  ui_story_31880601_45_dialog_content = "Para pengawal mengatakan bahwa kapal-kapal ini berani menghadapi ombak berbahaya dan badai mengaum untuk berdagang dengan negeri yang jauh.",
  ui_story_31880601_46_dialog_content = "Orang-orang tangguh di kapal-kapal ini menukar barang dengan emas dan sebaliknya.",
  ui_story_31880601_47_dialog_content = "Terus-menerus bepergian ke segala arah tanpa henti... Tak ada yang bisa memahami apa yang mendorong mereka untuk melakukannya.",
  ui_story_31880601_48_dialog_content = "Tapi aku tetap iri pada mereka semua.",
  ui_story_31880601_49_dialog_content = "Saya tidak akan iri pada mereka terlalu banyak. Perjalanan panjang seperti itu bisa sangat berbahaya.",
  ui_story_31880601_50_dialog_content = "Orang-orang di sini juga akan setuju. Para penjaga, pekerja di dermaga, dan semua orang lainnya.",
  ui_story_31880601_51_dialog_content = "Dengan setiap gelombang keberangkatan, selalu ada kapal yang tidak pernah kembali.",
  ui_story_31880601_52_dialog_content = "Mungkin mereka tersesat di laut, atau diserang oleh roh jahat samudra.",
  ui_story_31880601_53_dialog_content = "Ada cerita tentang pria yang jatuh cinta pada putri dewa laut, menikah dengan mereka, dan kehilangan segala harapan untuk kembali ke daratan.",
  ui_story_31880601_54_dialog_content = "Setiap kali sebuah kapal memulai pelayaran baru, selalu ada pembicaraan tentang takdir, bahaya, dan pertanda yang tak dapat dilihat...",
  ui_story_31880601_55_dialog_content = "Tapi meskipun segalanya, saya masih ingin naik salah satu kapal besar itu.",
  ui_story_31880601_56_dialog_content = "Meski tahu itu berbahaya? Kenapa kamu ingin melakukannya?",
  ui_story_31880601_57_dialog_content = "Karena selain kargo mereka, kapal-kapal ini juga membawa harapan dan impian banyak orang...",
  ui_story_31880601_58_dialog_content = "Dan saya ingin melihat sendiri tempat-tempat di mana harapan dan impian ini menjadi kenyataan!",
  ui_story_31880601_59_dialog_content = "Dengan begitu, saya mungkin menjadi seseorang yang mampu mewujudkan keinginan rakyat...",
  ui_story_31880601_60_dialog_content = "Kamu tahu... Bagaimana cara mengatakannya, ya...?",
  ui_story_31880601_61_dialog_content = "... Tidak apa-apa! Aku akan terdengar seperti gadis kecil yang sedang melamun...",
  ui_story_31880601_62_dialog_content = "Hahaha, jangan khawatir tentang itu! Saya yakin kamu akan bisa menyampaikan pendapatmu dengan jelas saat kamu semakin dewasa.",
  ui_story_31880601_63_dialog_content = "Tidak ada salahnya memiliki mimpi atau membicarakannya, dalam hal ini.",
  ui_story_31880601_64_dialog_content = "Aku setuju! Jadi saat aku besar nanti, aku pasti akan naik salah satu kapal itu!",
  ui_story_31880601_65_dialog_content = "Aku akan melihat sendiri apa yang ada di luar dan di bawah laut! Dan saat hari itu tiba, aku akan tahu persis bagaimana menggambarkan perasaan di hatiku.",
  ui_story_31880601_66_dialog_content = "Maka aku akan menunggumu di seberang laut.",
  ui_story_31880601_67_dialog_content = "Janji?",
  ui_story_31880601_68_dialog_content = "Aku berjanji.",
  ui_story_31880601_69_dialog_content = "... Kamu janji...?",
  ui_story_31880601_70_dialog_content = "Apakah aku...?",
  ui_story_31880601_71_dialog_content = "Ah, kamu sudah bangun. Tapi tidurmu nggak lama ya.",
  ui_story_31880601_72_dialog_content = "Apakah kamu bermimpi sesuatu?",
  ui_story_31880601_73_dialog_content = "Dantang...?",
  ui_story_31880601_74_dialog_content = "Hmm... Aku tidak ingat dengan jelas, tapi aku pasti baru saja bermimpi.",
  ui_story_31880601_75_dialog_content = "Benarkah? Kamu juga berbicara dalam tidur, menggumam tentang kapal dan janji-janji dan lainnya.",
  ui_story_31880601_76_dialog_content = "May Aku bertanya, apa yang kamu impikan?",
  ui_story_31880601_77_dialog_content = "Sulit untuk dijelaskan... Entah mengapa, rasanya seperti itu terjadi lama sekali...",
  ui_story_31880601_78_dialog_content = "Heheh, kamu memang orang yang menarik.",
  ui_story_31880601_79_dialog_content = "Melampaui waktu melalui mimpi... Gagasan tersebut pasti menginspirasi pemikiran.",
  ui_story_31880601_80_dialog_content = "Heh, aku janji aku tidak bermaksud membuatmu bingung atau apa pun. Menyampaikannya dalam kata-kata memang sedikit sulit...",
  ui_story_31880601_81_dialog_content = "Karena kemampuan psikis kita, memasuki dan menginterpretasikan mimpi menjadi cukup mudah...",
  ui_story_31880601_82_dialog_content = "Saya juga pernah menggunakan teknik mimpi serupa untuk melihat apa yang ada di dalam hati orang lain.",
  ui_story_31880601_83_dialog_content = "Ini membantu saya menyelesaikan banyak masalah di dunia nyata yang seharusnya tidak ada cara untuk saya selesaikan.",
  ui_story_31880601_84_dialog_content = "Itulah mengapa mimpi saya biasanya merupakan kombinasi informasi dari alam bawah sadar...",
  ui_story_31880601_85_dialog_content = "Sepertinya otakku bekerja lembur saat tidur, menyatukan potongan-potongan pengetahuan yang kudapatkan selama seharian...",
  ui_story_31880601_86_dialog_content = "Pfft—",
  ui_story_31880601_87_dialog_content = "Oh! Maaf, tadi aku nggak bicara aneh, kan...?",
  ui_story_31880601_88_dialog_content = "Sama sekali tidak! Lagi pula, kita sedang membahas tentang mimpi.",
  ui_story_31880601_89_dialog_content = "Mengingat kembali, saya cukup sering bermimpi selama masa pembentukan saya di Kerajaan Ji.",
  ui_story_31880601_90_dialog_content = "Terkadang aku bahkan bermimpi berada di atas kapal besar saat bersiap untuk pelayaran lain...",
  ui_story_31880601_91_dialog_content = "Apakah kamu masih bermimpi untuk pergi ke laut?",
  ui_story_31880601_92_dialog_content = "Tentu saja, meskipun mimpiku sekarang tidak lagi se-misterius dulu.",
  ui_story_31880601_93_dialog_content = "Tapi bagaimanapun juga, aku sudah pernah naik Colossus-mu sekarang.",
  ui_story_31880601_94_dialog_content = "Sekarang kamu menyebutkannya... Jika semua ini tidak pernah terjadi, apakah kamu masih ingin pergi ke laut?",
  ui_story_31880601_95_dialog_content = "Tidak bisa dipungkiri bahwa melakukan pelayaran di lautan sama saja dengan menyerahkan hidup Anda ke tangan takdir.",
  ui_story_31880601_96_dialog_content = "Tapi dengan memilih untuk pergi ke laut, bukankah itu sama saja dengan mengambil takdir ke tangan kita sendiri juga?",
  ui_story_31880601_97_dialog_content = "Tapi kamu masih mungkin berakhir di perut ikan raksasa.",
  ui_story_31880601_98_dialog_content = "Sejak saat aku dilahirkan, konon takdirku telah ditetapkan, dan orang-orang Kerajaan Ye menganggapku sebagai jiwa yang bernasib buruk.",
  ui_story_31880601_99_dialog_content = "Tapi dalam perjalanan saya, saya telah belajar bahwa takdir tidaklah sekekal yang kita percayai.",
  ui_story_31880601_100_dialog_content = "Inilah mengapa aku percaya bahwa kita sebagai manusia memiliki kekuatan untuk melawan yang tidak diketahui, bahkan langit itu sendiri.",
  ui_story_31880601_101_dialog_content = "Bagaimana denganmu? Apa yang akan kamu lakukan?",
  ui_story_31880601_102_dialog_content = "Jika Anda menghadapi kesempatan seperti ini, apakah Anda juga akan memilih untuk berlayar?",
  ui_story_31880601_103_option_content = "Aku akan pergi ke laut!",
  ui_story_31880601_104_dialog_content = "Seperti yang diharapkan, kita berpikiran sama.",
  ui_story_31880601_105_option_content = "Aku punya jalanku sendiri untuk ditempuh!",
  ui_story_31880601_106_dialog_content = "Kamu benar sekali. Lagi pula, takdirmu ada di tanganmu sendiri.",
  ui_story_31880601_107_dialog_content = "Tidak perlu mengikuti jejak orang lain, atau melakukan apa yang sudah mereka lakukan.",
  ui_story_31880601_108_dialog_content = "Kamu hanya perlu menjaga takdirmu sendiri dalam pandangan, dan menggenggamnya dengan kuat.",
  ui_story_31880601_109_dialog_content = "Dengan begitu, baik di laut maupun menghadapi perubahan yang tak terduga, kamu tidak akan pernah kehilangan arah.",
  ui_story_31880601_110_dialog_content = "Dan jika Anda kebetulan tersesat, yang perlu Anda lakukan hanyalah melihat ke belakang.",
  ui_story_31880601_111_dialog_content = "Selalu ada seseorang yang menunggumu.",
  ui_story_31880601_112_dialog_content = "Seharusnya aku tahu... Jawaban yang kamu temukan setelah dewasa...",
  ui_story_31880601_113_dialog_content = "Jauh lebih luar biasa daripada yang bisa kubayangkan!",
  ui_story_31880601_114_dialog_content = "Hmm? Aku tidak mengerti...",
  ui_story_31880601_115_dialog_content = "I-itu bukan apa-apa! Maaf mengganggu!",
  ui_story_31880601_116_dialog_content = "Sekarang di mana kita tadi... Oh—aku juga akan selalu menunggu di belakangmu, Dantang!",
  ui_story_31880601_117_dialog_content = "PlayerName…",
  ui_story_31880601_118_dialog_content = "Aku serius... Jadi, ayo terus berbicara... A-Aku janji aku... tidak terlalu lelah...",
  ui_story_31880601_119_dialog_content = "Oh? Sepertinya kita sudah begadang terlalu larut. Kamu juga butuh istirahat.",
  ui_story_31880601_120_dialog_content = "Bulan telah menyembunyikan dirinya di balik tabir awan gelap, jadi mari kita akhiri pemantauan malam ini untuk saat ini.",
  ui_story_31880601_121_dialog_content = "Izinkan saya untuk mengantar Anda kembali ke kamar Anda.",
  ui_story_31880601_122_dialog_content = "Mohon banyak istirahat. Akan ada banyak mimpi yang akan diwujudkan untuk kedua negeri di masa depan..."
}
return config
